package com.orangecode.tianmu.application;

import io.minio.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import com.orangecode.tianmu.utils.ContentTypeUtil;
import java.util.*;

/** Object names are generated by the host, never supplied by a browser. */
@Component
public class UploadObjects {
    private final MinioClient client;
    private final String bucket, origin, uploadOrigin;
    public UploadObjects(MinioClient client, @Value("${minio.bucket-name}") String bucket, @Value("${minio.url}") String origin,
            @Value("${minio.upload-url:${minio.url}}") String uploadOrigin) {
        this.client = client; this.bucket = bucket; this.origin = origin.replaceAll("/+$", "");
        this.uploadOrigin=uploadOrigin.replaceAll("/+$", "");
    }
    String chunk(String id, int index) { return "uploads/" + id + "/chunks/" + index; }
    public record Part(String url, Map<String,String> fields) {}
    public Part sign(String id, int index, long size) {
        try {
            // S3 presigned PUT excludes Content-Length from its signed headers. POST policy enforces the actual file size.
            var policy=new PostPolicy(bucket,java.time.ZonedDateTime.now(java.time.ZoneOffset.UTC).plusMinutes(15));
            String key=chunk(id,index);policy.addEqualsCondition("key",key);policy.addContentLengthRangeCondition(Math.toIntExact(size),Math.toIntExact(size));
            var fields=new HashMap<>(client.getPresignedPostFormData(policy));fields.put("key",key);
            return new Part(uploadOrigin+"/"+bucket,Map.copyOf(fields));
        } catch (Exception e) { throw new IllegalStateException("Upload signing unavailable", e); }
    }
    public Set<Integer> progress(String id, UploadPolicy.Request request) {
        try {
            var result = new HashSet<Integer>();
            for (var entry : client.listObjects(ListObjectsArgs.builder().bucket(bucket).prefix("uploads/"+id+"/chunks/").recursive(true).build())) {
                var item = entry.get(); String tail = item.objectName().substring(item.objectName().lastIndexOf('/')+1);
                if (tail.matches("[0-9]{1,3}")) { int index = Integer.parseInt(tail);
                    if (index < request.chunks() && item.size() == request.chunkSize(index)) result.add(index);
                }
            }
            return Set.copyOf(result);
        } catch (Exception e) { throw new IllegalStateException("Upload progress unavailable", e); }
    }
    public String compose(String id, long fence, UploadPolicy.Request request) {
        try {
            long deadline = System.nanoTime() + java.time.Duration.ofMinutes(3).toNanos();
            var sources = new ArrayList<ComposeSource>();
            for (int i=0;i<request.chunks();i++) {
                if (System.nanoTime() > deadline) throw new IllegalStateException("Merge verification deadline exceeded");
                var stat = client.statObject(StatObjectArgs.builder().bucket(bucket).object(chunk(id,i)).build());
                if (stat.size()!=request.chunkSize(i)) throw new IllegalStateException("Invalid chunk size");
                sources.add(ComposeSource.builder().bucket(bucket).object(chunk(id,i)).matchETag(stat.etag()).build());
            }
            // Different lease holders never overwrite one another's final object.
            String key = "upload_"+id+"_"+fence+"."+request.fileType();
            client.composeObject(ComposeObjectArgs.builder().bucket(bucket).object(key).sources(sources)
                    .headers(Map.of("Content-Type",new ContentTypeUtil().getType(request.fileType()))).build());
            return origin+"/"+bucket+"/"+key;
        } catch (Exception e) { throw new IllegalStateException("Upload merge unavailable; retry the same upload", e); }
    }
    public void clean(String id, String retainedUrl) {
        try {
            String retainedPath=retainedUrl==null?null:java.net.URI.create(retainedUrl).getPath();
            for(String prefix:List.of("uploads/"+id+"/", "upload_"+id+"_"))
                for (var entry : client.listObjects(ListObjectsArgs.builder().bucket(bucket).prefix(prefix).recursive(true).build())) {
                    String key=entry.get().objectName();
                    if (!("/"+bucket+"/"+key).equals(retainedPath)) client.removeObject(RemoveObjectArgs.builder().bucket(bucket).object(key).build());
                }
        } catch (Exception e) { throw new IllegalStateException("Upload cleanup will retry", e); }
    }
}
